          const target = polygon.cap ? capPositions : fragmentPositions;
          target.push(...point.p);
          if (!polygon.cap) {
            fragmentPiece.push(piece);
            if (uvs) fragmentUvs.push(...(point.uv || [0, 0]));
          }
        }
        if (polygon.cap) {
          capPieces.push(piece);
