  positions.set(parts.capPositions, fragmentVertices * 3);
  for (let vertex = fragmentVertices; vertex < vertexCount; vertex += 1) {
    pieceIds[vertex] = parts.capPieces[Math.floor((vertex - fragmentVertices) / 3)] || 0;
