      centroids[piece * 3] = sums[piece * 3] / counts[piece];
      centroids[piece * 3 + 1] = sums[piece * 3 + 1] / counts[piece];
      centroids[piece * 3 + 2] = sums[piece * 3 + 2] / counts[piece];
