          value: 1,
          step: 1,
          decimals: 0,
        },
        closed: {
          name: "Inner faces",
          type: PZ.property.type.OPTION,
          value: 1,
          items: "open;closed",
        },
        colors: {
          name: "Fragment colors",
          type: PZ.property.type.OPTION,
          value: 1,
          items: "material;random",
        },
        distance: {
          dynamic: true,
          name: "Distance",
          type: PZ.property.type.NUMBER,
          value: 0,
          min: -1000,
          max: 1000,
          step: 1,
          decimals: 2,
        },
        offset: {
          dynamic: true,
          name: "Offset fragments",
          type: PZ.property.type.NUMBER,
          value: 0,
          min: 0,
          max: 100,
          step: 1,
          decimals: 1,
        },
        scatter: {
          dynamic: true,
          name: "Scatter",
          type: PZ.property.type.NUMBER,
          value: 0,
          min: -1000,
          max: 1000,
          step: 1,
          decimals: 2,
        },
        spin: {
          dynamic: true,
          name: "Spin",
          type: PZ.property.type.NUMBER,
          value: 0,
          min: -3600,
          max: 3600,
          step: 1,
          decimals: 1,
          scaleFactor: DEGREES_TO_RADIANS,
        },
        field: {
          name: "Field",
          type: PZ.property.type.OPTION,
          value: 0,
          items: "infinite;linear;box;sphere",
        },
        fieldPosition: {
          name: "Field position",
          type: PZ.property.type.VECTOR3,
          value: [0, 0, 0],
          step: 1,
          decimals: 1,
        },
        fieldScale: {
          name: "Field scale",
          type: PZ.property.type.VECTOR3,
          value: [100, 100, 100],
